    import bpy
    from pathlib import Path
    from mathutils import Vector

    scene = bpy.context.scene
    scene.frame_start = 1
    scene.frame_end = 90

    cache_dir = str(Path(globals().get('CACHE_DIR', '/tmp/campfire_cache')).resolve())
