    if bpy.ops.object.mode_set.poll():
        try:
            bpy.ops.object.mode_set(mode='OBJECT')
        except Exception:
            pass

    domain_obj = None
    emitter_obj = None
    support_objs = []
    bounds = []

    for obj in bpy.data.objects:
        if obj.type != 'MESH':
            continue
        lname = obj.name.lower()
        if domain_obj is None and 'domain' in lname:
            domain_obj = obj
        if emitter_obj is None and ('emitter' in lname or 'flow' in lname or 'fire_source' in lname):
            emitter_obj = obj
        if any(token in lname for token in ('log', 'stone', 'rock', 'ground', 'earth', 'dirt', 'ember', 'coal', 'fire')):
            support_objs.append(obj)
            try:
                for corner in obj.bound_box:
                    bounds.append(obj.matrix_world @ Vector(corner))
            except Exception:
                bounds.append(obj.location.copy())

    if emitter_obj is None:
        for obj in support_objs:
            lname = obj.name.lower()
            if 'ember' in lname or 'coal' in lname:
                emitter_obj = obj
                break

    if bounds:
        center = sum(bounds, Vector((0.0, 0.0, 0.0))) / len(bounds)
        min_z = min(v.z for v in bounds)
        max_z = max(v.z for v in bounds)
    else:
        center = Vector((0.0, 0.0, 0.0))
        min_z = 0.0
        max_z = 0.25

    if domain_obj is None:
        bpy.ops.mesh.primitive_cube_add(size=1.0, location=(center.x, center.y, max_z + 0.75))
        domain_obj = bpy.context.active_object
        domain_obj.name = 'CampfireDomain'
        domain_obj.scale = (1.2, 1.2, 1.4)
    else:
        domain_obj.name = 'CampfireDomain'

    domain_obj.display_type = 'WIRE'
    domain_obj.visible_shadow = False

    if emitter_obj is None:
        bpy.ops.mesh.primitive_uv_sphere_add(radius=0.12, location=(center.x, center.y, min_z + 0.10))
        emitter_obj = bpy.context.active_object
        emitter_obj.name = 'CampfireEmitter'
        emitter_obj.scale = (1.0, 1.0, 0.35)
