    if hasattr(fs, 'use_initial_velocity'):
        fs.use_initial_velocity = True
    if hasattr(fs, 'velocity_normal'):
        fs.velocity_normal = 0.2
    if hasattr(fs, 'velocity_random'):
        fs.velocity_random = 0.2

    for obj in support_objs:
        if obj == domain_obj or obj == emitter_obj or obj.type != 'MESH':
            continue
        effector_mod = None
        for mod in obj.modifiers:
            if mod.type == 'FLUID':
                effector_mod = mod
                break
        if effector_mod is None:
            effector_mod = obj.modifiers.new(name='Fluid', type='FLUID')
        if effector_mod is not None:
            effector_mod.fluid_type = 'EFFECTOR'

